package gg.pixelkingdomwars.nativeclient.ordinaryequipment
import gg.pixelkingdomwars.nativeclient.charter.*
import gg.pixelkingdomwars.nativeclient.starter.*
import gg.pixelkingdomwars.nativeclient.vehicle.*
import kotlinx.serialization.json.*
import org.junit.Assert.*
import org.junit.Test
class SurveyLensProtocolTest {
 private val f=Json.parseToJsonElement(requireNotNull(javaClass.getResource("/survey-lens.json")).readText()).jsonObject
 private val old=Json.parseToJsonElement(requireNotNull(javaClass.getResource("/ordinary-equipment.json")).readText()).jsonObject
 private val policy=EquipmentPolicy.from(f.charterObject("policy"));private val base=f.charterObject("view").charterText("baseId");private val identity=StarterIdentity("https://lens.test","devnet",f.charterObject("view").charterText("wallet"))
 private val route=f.charterObject("starterEnvelope").charterObject("receipt").charterObject("route")
 private fun change(o:JsonObject,path:String,value:JsonElement):JsonObject{val p=path.split('.',limit=2);return JsonObject(o+(p[0] to if(p.size==1)value else change(o.charterObject(p[0]),p[1],value)))}
 private fun reject(block:()->Unit){assertThrows(Exception::class.java,block)}
 private fun starter(proof:JsonObject){EquipmentGrammar.starterProof(proof,identity,f.charterObject("starterEnvelope").charterObject("receipt").charterObject("request"),route,policy)}
 private fun vehicle():VehiclePolicy{val raw=Json.parseToJsonElement(requireNotNull(javaClass.getResource("/vehicle-client-vectors.json")).readText()).jsonObject.charterObject("constants");return VehiclePolicy.from(JsonObject(raw+("ordinaryEquipment" to policy.raw)))}
 @Test fun `explicit catalogue two binds both recipes stocks and per item pending output`() {val view=EquipmentView.from(f.charterObject("view"));assertEquals(2,view.catalogueVersion);view.recipes.forEach(policy::verify);val request=EquipmentGrammar.craftRequest(f.charterObject("request"));EquipmentProof.from(f.charterObject("envelope"),identity,EquipmentCommand(request,view.recipes.single{it.recipeId==request.recipeId}));assertNull(EquipmentView.from(old.charterObject("view")).catalogueVersion);assertEquals(old.charterObject("policy"),EquipmentPolicy.from(old.charterObject("policy")).raw)}
 @Test fun `missing catalogue duplicate stocks wrong ingredients and cross item pending output reject`() {val view=f.charterObject("view");reject{EquipmentView.from(JsonObject(view-"catalogueVersion"))};reject{EquipmentView.from(JsonObject(view+("catalogueVersion" to JsonNull)))};reject{EquipmentView.from(JsonObject(view+("equipmentStock" to JsonArray(view.getValue("equipmentStock").jsonArray.reversed()))))};val recipe=EquipmentView.from(view).recipes.last();reject{policy.verify(recipe.copy(inputs=recipe.inputs.reversed()))};reject{EquipmentView.from(JsonObject(view+("pendingJobs" to JsonArray(emptyList()))))}}
 @Test fun `starter companion conserves original cargo without speed gain and returns exact proof`() {EquipmentGrammar.starterView(f.charterObject("starterView"),policy);starter(f.charterObject("starterEnvelope"));starter(f.charterObject("starterReturnedEnvelope"));val original=policy.original(route);assertEquals(route["durationSec"],original["durationSec"]);assertEquals("25",original.charterText("grossQuantity"));assertEquals("5",route.charterObject("secondaryOutput").charterText("grossQuantity"));assertFalse("secondaryOutput" in original)}
 @Test fun `both legs resource tax amount duration and frozen originals must be exact`() {for((path,value)in listOf("secondaryOutput.resourceId" to JsonPrimitive("heartwood_logs"),"secondaryOutput.grossQuantity" to JsonPrimitive("-1"),"secondaryOutput.netQuantity" to JsonPrimitive("5"),"secondaryOutput.islandPoolQuantity" to JsonPrimitive("0"),"secondaryOutput.grossQuantity" to JsonPrimitive("9223372036854775808"),"durationSec" to JsonPrimitive(1),"fitting.originalGrossQuantity" to JsonPrimitive("30"),"fitting.resourceId" to JsonPrimitive("crown_iron_ore")))reject{policy.original(change(route,path,value))};reject{policy.original(JsonObject(route-"secondaryOutput"))};reject{policy.original(JsonObject(route-"fitting"))};reject{policy.original(JsonObject(route+("secondaryOutput" to JsonNull)))}}
 @Test fun `return cannot omit alter or add a companion independently of accepted departure`() {val returned=f.charterObject("starterReturnedEnvelope");reject{starter(JsonObject(returned+("return" to JsonObject(returned.charterObject("return")-"secondaryOutput"))))};reject{starter(change(returned,"return.secondaryOutput.resourceId",JsonPrimitive("heartwood_logs")))};val v=vehicle();v.verifyExpedition(f.charterObject("advancedReturnedEnvelope"));reject{v.verifyExpedition(change(f.charterObject("advancedReturnedEnvelope"),"return.secondaryOutput",JsonNull))}}
 @Test fun `advanced route original economics supplies and request selection remain bound`() {val v=vehicle();v.verifyRoutes(VehicleProtocol.routes(f.charterObject("advancedView")),1);v.verifyExpedition(f.charterObject("advancedEnvelope"));val r=f.charterObject("advancedEnvelope").charterObject("receipt").charterObject("route");assertEquals(r["supplies"],policy.original(r)["supplies"]);reject{v.verifyExpedition(change(f.charterObject("advancedEnvelope"),"receipt.request.fitting.resourceId",JsonPrimitive("heartwood_logs")))};v.verifyExpedition(old.charterObject("advancedEnvelope"))}
 @Test fun `only explicit Lens query can select one common material`() {for(path in listOf("/starter-expeditions","/vehicles/client/routes"))EquipmentGrammar.request("GET",path,mapOf("baseId" to base,"fitting" to "survey_lens","resourceId" to "frost_quartz"),null);EquipmentGrammar.request("GET","/ordinary-equipment",mapOf("baseId" to base,"catalogueVersion" to "2"),null)
  for(query in listOf(mapOf("resourceId" to "frost_quartz"),mapOf("fitting" to "survey_lens"),mapOf("fitting" to "route_compass","resourceId" to "frost_quartz"),mapOf("fitting" to "survey_lens","resourceId" to "gems")))reject{EquipmentGrammar.request("GET","/starter-expeditions",mapOf("baseId" to base)+query,null)};reject{EquipmentGrammar.request("GET","/ordinary-equipment",mapOf("baseId" to base,"catalogueVersion" to "3"),null)}}
 @Test fun `legacy fitted flight remains readable while paused and rejects missing companion`() {val plain=policy.original(route);val routes=starterRouteIds.map{id->val common=id.startsWith("common_");val realm=if(common)id.removePrefix("common_").replace('_','-')else "crownlands";JsonObject(plain+mapOf("routeId" to JsonPrimitive(id),"realmId" to JsonPrimitive(realm),"resourceId" to JsonPrimitive(starterResourceRealms.entries.single{it.value==realm}.key))+if(common)mapOf("access" to buildJsonObject{put("kind","starter_common");put("policyVersion",1)})else emptyMap())};val receipt=f.charterObject("starterEnvelope").charterObject("receipt");val raw=JsonObject(f.charterObject("starterView")-"fitting"+mapOf("routes" to JsonArray(routes),"acceptingDepartures" to JsonPrimitive(false),"flight" to JsonObject(receipt-setOf("wallet","request"))));val parsed=StarterExpeditionView.from(raw);assertEquals("frost_quartz",parsed.flight!!.route.secondaryOutput!!.resourceId);reject{StarterExpeditionView.from(change(raw,"flight.route.secondaryOutput",JsonNull))}}
 @Test fun `Compass cannot acquire a secondary leg and Lens requires independently installed policy`() {val compass=old.charterObject("starterEnvelope").charterObject("receipt").charterObject("route");reject{policy.original(JsonObject(compass+("secondaryOutput" to route.getValue("secondaryOutput"))))};reject{EquipmentPolicy.from(old.charterObject("policy")).original(route)};assertEquals(EquipmentPolicy.from(old.charterObject("policy")).original(compass),policy.original(compass))}
}
